#!/usr/bin/env node
// Generates every port's token files, stylesheets, scripts, fonts and images
// from design/: tokens.json, assets/css, assets/js, assets/fonts and assets/img.
// Usage: node tools/build-tokens.mjs [--check]
// --check writes nothing and exits 1 when any generated file is out of date.

import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'design/tokens.json'), 'utf8'));
const THEME_SCHEMA = 'https://schemas.wp.org/wp/6.9/theme.json';

const PX_PER_REM = 16;

function toRem(length) {
	const match = /^(-?\d*\.?\d+)(rem|px)$/.exec(String(length).trim());
	if (!match) throw new Error(`expected a rem or px length, got: ${length}`);
	return match[2] === 'rem' ? Number(match[1]) : Number(match[1]) / PX_PER_REM;
}

const trim = (n) => String(Number(n.toFixed(4)));

// A font size is either fixed ({ value }) or fluid ({ min, max }). A fluid size
// is the straight line from min at fluidViewport.min to max at fluidViewport.max,
// the same line WordPress draws from settings.typography.fluid, so tokens.css
// and theme.json render identical sizes at every width.
function fontSizeCss(size) {
	if (size.value !== undefined) return size.value;
	const vpMin = toRem(tokens.fluidViewport.min);
	const vpMax = toRem(tokens.fluidViewport.max);
	const min = toRem(size.min);
	const max = toRem(size.max);
	const slope = (max - min) / (vpMax - vpMin);
	const intercept = min - slope * vpMin;
	return `clamp(${size.min}, ${trim(intercept)}rem + ${trim(slope * 100)}vw, ${size.max})`;
}

function fontSizeNote(size) {
	const px = (length) => trim(toRem(length) * PX_PER_REM);
	return size.value !== undefined ? `${px(size.value)}px` : `${px(size.min)} -> ${px(size.max)}px`;
}

function cssBlock(lines) {
	const width = Math.max(...lines.filter((l) => l.note).map((l) => l.text.length)) + 2;
	return lines
		.map(({ text, note }) => (note ? `${text.padEnd(width)}/* ${note} */` : text))
		.join('\n');
}

function colorLines(mode, withNotes) {
	return Object.entries(tokens.color).map(([slug, t]) => ({
		text: `  --color-${slug}: ${t[mode]};`,
		note: withNotes ? t.note?.[mode] : undefined,
	}));
}

function buildTokensCss() {
	const { light, dark } = tokens.modes;
	const fonts = Object.entries(tokens.fontFamily).map(([slug, f]) => ({ text: `  --font-${slug}: ${f.stack};` }));
	const sizes = Object.entries(tokens.fontSize).map(([slug, s]) => ({ text: `  --size-${slug}: ${fontSizeCss(s)};`, note: fontSizeNote(s) }));
	const spaces = Object.entries(tokens.spacing).map(([slug, s]) => ({ text: `  --space-${slug}: ${s.value};`, note: s.note }));
	const widths = Object.entries(tokens.width).map(([slug, v]) => ({ text: `  --width-${slug}: ${v};` }));
	const custom = Object.entries(tokens.custom).map(([slug, c]) => ({ text: `  --${slug}: ${c.value};`, note: c.note }));
	const vp = tokens.fluidViewport;

	return `/*
 * Readerly — design tokens
 * ---------------------------------------------------------------
 * GENERATED from design/tokens.json by tools/build-tokens.mjs.
 * Edit tokens.json and rerun the script; do not edit this file.
 *
 * Porting map
 *   WordPress  theme.json settings.color.palette   -> --color-*
 *              settings.typography.fontFamilies    -> --font-*
 *              settings.typography.fontSizes       -> --size-*
 *              settings.spacing.spacingSizes       -> --space-*
 *              settings.layout.contentSize/wideSize-> --width-*
 *              settings.custom                     -> "supporting values"
 *   Hugo / Jekyll / Ghost: copy this file as-is.
 *
 * Light ("${light.title}") is the default. Dark ("${dark.title}") applies through
 * prefers-color-scheme, and [data-theme="light" | "dark"] on <html> overrides
 * the system. Both modes use the same token names; only the values change.
 */

:root {
  color-scheme: light;

  /* Colour palette — light ("${light.title.toLowerCase()}") */
${cssBlock(colorLines('light', true))}

  /* Font families (bundled in assets/fonts, SIL Open Font License) */
${cssBlock(fonts)}

  /* Fluid font sizes: min at ${vp.min} wide, max at ${vp.max} wide */
${cssBlock(sizes)}

  /* Spacing scale (4/8 rhythm; the larger steps breathe with the viewport) */
${cssBlock(spaces)}

  /* Layout widths */
${cssBlock(widths)}

  /* Supporting values (theme.json settings.custom) */
${cssBlock(custom)}
}

/* Dark ("${dark.title.toLowerCase()}") — same names, independently chosen values.
   Kept identical in both blocks below: system preference and explicit override. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
${cssBlock(colorLines('dark', true)).replace(/^/gm, '  ')}
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
${cssBlock(colorLines('dark', false))}
}
`;
}

function palette(mode) {
	return Object.entries(tokens.color).map(([slug, t]) => ({ color: t[mode], name: t.name, slug: t.wordpressSlug ?? slug }));
}

function setPath(object, path, value) {
	let node = object;
	for (const key of path.slice(0, -1)) {
		node[key] ??= {};
		node = node[key];
	}
	node[path.at(-1)] = value;
}

function readJson(file, fallback) {
	return existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : fallback;
}

function fontFaces(family) {
	const { styles, subsets } = tokens.fontFace;
	return styles.flatMap((style) =>
		Object.entries(subsets).map(([subset, unicodeRange]) => ({
			family: family.name,
			style,
			weight: family.weight,
			file: `${family.files}/${family.files}-${subset}-standard-${style}.woff2`,
			unicodeRange,
		})),
	);
}

function buildFontsCss() {
	const faces = Object.values(tokens.fontFamily).flatMap(fontFaces);
	const rules = faces.map(
		(f) => `@font-face {
  font-family: "${f.family}";
  font-style: ${f.style};
  font-weight: ${f.weight};
  font-display: swap;
  src: url("../fonts/${f.file}") format("woff2");
  unicode-range: ${f.unicodeRange};
}`,
	);
	return `/*
 * Readerly — bundled fonts, under the SIL Open Font License (OFL.txt beside each font)
 * GENERATED from design/tokens.json by tools/build-tokens.mjs. Do not edit.
 */

${rules.join('\n\n')}
`;
}

function buildJekyllCss() {
	const read = (path) => readFileSync(join(root, path), 'utf8');
	return `/* Readerly for Jekyll. GENERATED by tools/build-tokens.mjs from design/assets/css. Do not edit. */

${buildFontsCss()}
${buildTokensCss()}
${read('design/assets/css/style.css')}`;
}

function buildHugoCss() {
	const read = (path) => readFileSync(join(root, path), 'utf8');
	return `/* Readerly for Hugo. GENERATED by tools/build-tokens.mjs from design/assets/css. Do not edit. */

${buildFontsCss()}
${buildTokensCss()}
${read('design/assets/css/style.css')}`;
}

function buildThemeJson(file) {
	const theme = readJson(file, { $schema: THEME_SCHEMA, version: 3, settings: {}, styles: {} });

	setPath(theme, ['settings', 'color', 'palette'], palette('light'));
	setPath(
		theme,
		['settings', 'typography', 'fontFamilies'],
		Object.entries(tokens.fontFamily).map(([slug, f]) => ({
			name: f.name,
			slug,
			fontFamily: f.stack,
			fontFace: fontFaces(f).map((face) => ({
				fontFamily: face.family,
				fontStyle: face.style,
				fontWeight: face.weight,
				fontDisplay: 'swap',
				src: [`file:./assets/fonts/${face.file}`],
				unicodeRange: face.unicodeRange,
			})),
		})),
	);
	const existingFluid = theme.settings?.typography?.fluid;
	setPath(theme, ['settings', 'typography', 'fluid'], {
		...(typeof existingFluid === 'object' && existingFluid !== null ? existingFluid : {}),
		minViewportWidth: tokens.fluidViewport.min,
		maxViewportWidth: tokens.fluidViewport.max,
	});
	setPath(
		theme,
		['settings', 'typography', 'fontSizes'],
		Object.entries(tokens.fontSize).map(([slug, s]) =>
			s.value !== undefined
				? { name: s.name, slug, size: s.value, fluid: false }
				: { name: s.name, slug, size: s.max, fluid: { min: s.min, max: s.max } },
		),
	);
	setPath(
		theme,
		['settings', 'spacing', 'spacingSizes'],
		Object.entries(tokens.spacing).map(([slug, s]) => ({ name: s.name, slug, size: s.value })),
	);
	setPath(theme, ['settings', 'layout', 'contentSize'], tokens.width.content);
	setPath(theme, ['settings', 'layout', 'wideSize'], tokens.width.wide);
	setPath(
		theme,
		['settings', 'custom'],
		Object.fromEntries(Object.entries(tokens.custom).map(([slug, c]) => [slug, c.value])),
	);
	return `${JSON.stringify(theme, null, '\t')}\n`;
}

function buildDarkVariation(file) {
	const variation = readJson(file, { $schema: THEME_SCHEMA, version: 3, title: tokens.modes.dark.title });
	variation.title = tokens.modes.dark.title;
	setPath(variation, ['settings', 'color', 'palette'], palette('dark'));
	return `${JSON.stringify(variation, null, '\t')}\n`;
}

// Copies every file in src (or only the names listed) to dst. Files in dst
// that are not in the copy set are stale, so dst holds exactly the copies.
function mirror(src, dst, names) {
	const walk = (base, dir = '') =>
		readdirSync(join(root, base, dir), { withFileTypes: true }).flatMap((entry) =>
			entry.isDirectory() ? walk(base, join(dir, entry.name)) : [join(dir, entry.name)],
		);
	const files = names ?? walk(src);
	const extra = existsSync(join(root, dst)) ? walk(dst).filter((f) => !files.includes(f)) : [];
	return {
		copies: files.map((f) => [join(dst, f), () => readFileSync(join(root, src, f))]),
		extra: extra.map((f) => join(dst, f)),
	};
}

const mirrors = [
	mirror('design/assets/fonts', 'wordpress/assets/fonts'),
	mirror('design/assets/fonts', 'jekyll/theme/assets/fonts'),
	mirror('design/assets/img', 'jekyll/theme/assets/img', ['paper-grain.svg', 'cover-grain.svg']),
	mirror('design/assets/covers', 'jekyll/demo/assets/covers'),
	mirror('design/assets/img', 'jekyll/demo/assets/img', ['avatar-nora.svg', 'portrait-isobel.svg', 'still-life.svg', 'favicon.svg']),
	mirror('design/assets/fonts', 'hugo/theme/static/readerly/fonts'),
	mirror('design/assets/img', 'hugo/theme/static/readerly/img', ['paper-grain.svg', 'cover-grain.svg']),
	mirror('design/assets/covers', 'hugo/theme/exampleSite/static/assets/covers'),
	mirror('design/assets/img', 'hugo/theme/exampleSite/static/assets/img', ['avatar-nora.svg', 'portrait-isobel.svg', 'still-life.svg', 'favicon.svg']),
];

const outputs = [
	['design/assets/css/tokens.css', () => buildTokensCss()],
	['design/assets/css/fonts.css', () => buildFontsCss()],
	['wordpress/theme.json', (file) => buildThemeJson(file)],
	['wordpress/styles/lamplight.json', (file) => buildDarkVariation(file)],
	['jekyll/theme/assets/css/readerly.css', () => buildJekyllCss()],
	['jekyll/theme/assets/js/theme.js', () => readFileSync(join(root, 'design/assets/js/theme.js'))],
	['hugo/theme/assets/readerly/css/readerly.css', () => buildHugoCss()],
	['hugo/theme/assets/readerly/js/theme.js', () => readFileSync(join(root, 'design/assets/js/theme.js'))],
	...mirrors.flatMap((m) => m.copies),
];

// The Ghost theme (ghost/) ships the same stylesheet and script as Jekyll, plus
// its own ghost.css for Koenig cards and members forms, which is not generated.
const ghostMirrors = [
	mirror('design/assets/fonts', 'ghost/assets/fonts'),
	mirror('design/assets/img', 'ghost/assets/img', ['paper-grain.svg', 'cover-grain.svg']),
];
mirrors.push(...ghostMirrors);
outputs.push(
	['ghost/assets/css/readerly.css', () => {
		const css = buildJekyllCss();
		if (!css.startsWith('/* Readerly for Jekyll.')) throw new Error('buildJekyllCss() banner changed: update the Ghost banner swap');
		return css.replace('Readerly for Jekyll.', 'Readerly for Ghost.');
	}],
	['ghost/assets/js/theme.js', () => readFileSync(join(root, 'design/assets/js/theme.js'))],
	...ghostMirrors.flatMap((m) => m.copies),
);

const check = process.argv.includes('--check');
const stale = [];
for (const [path, build] of outputs) {
	const file = join(root, path);
	const next = build(file);
	const current = existsSync(file) ? readFileSync(file) : null;
	if (current && current.equals(Buffer.from(next))) continue;
	stale.push(path);
	if (!check) {
		mkdirSync(dirname(file), { recursive: true });
		writeFileSync(file, next);
	}
}
for (const path of mirrors.flatMap((m) => m.extra)) {
	stale.push(`${path} (not generated, delete it)`);
	if (!check) rmSync(join(root, path));
}

if (check && stale.length) {
	console.error(`Out of date (run node tools/build-tokens.mjs):\n  ${stale.join('\n  ')}`);
	process.exit(1);
}
console.log(stale.length ? `Wrote ${stale.join(', ')}` : 'Generated files are up to date.');
